package com.example.baget.reports;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.*;
/** Small server-side OOXML writer: typed numbers and literal strings, no executable formulas. */
public final class ReportWorkbook {
 private ReportWorkbook(){}
 public record Table(String title,List<String> notes,List<List<Object>> summary,List<String> headers,List<List<Object>> rows){}
 static String xml(Object x){String s=Objects.toString(x,"");StringBuilder out=new StringBuilder();s.codePoints().filter(c->c==9||c==10||c==13||c>=32&&c<=0xD7FF||c>=0xE000&&c<=0xFFFD||c>=0x10000&&c<=0x10FFFF).limit(32767).forEach(out::appendCodePoint);return out.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String column(int n){String s="";for(n++;n>0;n=(n-1)/26)s=(char)('A'+(n-1)%26)+s;return s;}
 static void row(StringBuilder out,int index,List<?> values,int style){out.append("<row r=\"").append(index).append("\" ht=\"30\" customHeight=\"1\">");for(int c=0;c<values.size();c++){Object v=values.get(c);String ref=column(c)+index;if(v instanceof Number)out.append("<c r=\"").append(ref).append("\" s=\"2\"><v>").append(xml(v)).append("</v></c>");else out.append("<c r=\"").append(ref).append("\" s=\"").append(style).append("\" t=\"inlineStr\"><is><t xml:space=\"preserve\">").append(xml(v)).append("</t></is></c>");}out.append("</row>");}
 public static byte[] write(Table table){
  try(var bytes=new ByteArrayOutputStream();var zip=new ZipOutputStream(bytes,StandardCharsets.UTF_8)){
   put(zip,"[Content_Types].xml","<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/></Types>");
   put(zip,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
   put(zip,"xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Звіт\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");
   put(zip,"xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/><Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");
   put(zip,"xl/styles.xml","<styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><numFmts count=\"1\"><numFmt numFmtId=\"164\" formatCode=\"#,##0.00##\"/></numFmts><fonts count=\"2\"><font><sz val=\"11\"/><name val=\"Calibri\"/></font><font><b/><sz val=\"11\"/><name val=\"Calibri\"/></font></fonts><fills count=\"2\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill></fills><borders count=\"1\"><border/></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"3\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment vertical=\"top\" wrapText=\"1\"/></xf><xf numFmtId=\"0\" fontId=\"1\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyAlignment=\"1\"><alignment wrapText=\"1\"/></xf><xf numFmtId=\"164\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyNumberFormat=\"1\"/></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>");
   int header=table.notes().size()+table.summary().size()+4;StringBuilder sheet=new StringBuilder("<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"").append(header).append("\" topLeftCell=\"A").append(header+1).append("\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><cols><col min=\"1\" max=\"").append(table.headers().size()).append("\" width=\"32\" customWidth=\"1\"/></cols><sheetData>");
   int i=1;row(sheet,i++,List.of(table.title()),1);for(String note:table.notes())row(sheet,i++,List.of(note),0);i++;for(var values:table.summary())row(sheet,i++,values,1);i++;row(sheet,i++,table.headers(),1);for(var values:table.rows())row(sheet,i++,values,0);sheet.append("</sheetData><autoFilter ref=\"A").append(header).append(":").append(column(table.headers().size()-1)).append(i-1).append("\"/>");sheet.append("<mergeCells count=\"").append(table.notes().size()+1).append("\">");for(int n=1;n<=table.notes().size()+1;n++)sheet.append("<mergeCell ref=\"A").append(n).append(":").append(column(table.headers().size()-1)).append(n).append("\"/>");sheet.append("</mergeCells><pageMargins left=\"0.3\" right=\"0.3\" top=\"0.5\" bottom=\"0.5\" header=\"0.2\" footer=\"0.2\"/><pageSetup orientation=\"landscape\" paperSize=\"9\" fitToWidth=\"1\" fitToHeight=\"0\"/></worksheet>");
   put(zip,"xl/worksheets/sheet1.xml",sheet.toString());zip.finish();return bytes.toByteArray();
  }catch(IOException e){throw new UncheckedIOException(e);}
 }
 private static void put(ZipOutputStream zip,String path,String body)throws IOException{zip.putNextEntry(new ZipEntry(path));zip.write(("<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>"+body).getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
}
